//! The shadcn Nova Button visual port.
//!
//! Visual source: shadcn/ui 4.19.0 `button.tsx` and `style-nova.css` at
//! `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`. Interaction comes from the
//! pinned Base GPUI `ButtonRoot`.

use std::rc::Rc;

use base_gpui::button::ButtonRoot;
use gpui::{
    AnyElement, App, ClickEvent, Div, ElementId, FontWeight, InteractiveElement as _, IntoElement,
    ParentElement, RenderOnce, SharedString, Styled, Window, prelude::FluentBuilder as _, px,
};

use super::theme::{ThemeMode, UiRadius, UiTheme};

type ButtonClickHandler = Rc<dyn Fn(&ClickEvent, &mut Window, &mut App) + 'static>;

/// The pinned shadcn Button visual variant.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ButtonVariant {
    /// Primary action.
    #[default]
    Default,
    /// Bordered action.
    Outline,
    /// Secondary action.
    Secondary,
    /// Low-emphasis action.
    Ghost,
    /// Destructive action.
    Destructive,
    /// Link-styled action.
    Link,
}

/// The pinned shadcn Button size.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ButtonSize {
    /// 24px-high extra-small button.
    Xs,
    /// 28px-high small button.
    Sm,
    /// 32px-high default button.
    #[default]
    Default,
    /// 36px-high large button.
    Lg,
    /// 24px square icon button.
    IconXs,
    /// 28px square icon button.
    IconSm,
    /// 32px square icon button.
    Icon,
    /// 36px square icon button.
    IconLg,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct ButtonMetrics {
    height: f32,
    horizontal_padding: f32,
    gap: f32,
    radius: f32,
    text_size: f32,
    icon_only: bool,
}

impl ButtonSize {
    fn metrics(self, radii: UiRadius) -> ButtonMetrics {
        let radius = f32::from(radii.lg);
        let radius_md = f32::from(radii.md);
        match self {
            Self::Xs => ButtonMetrics::new(24.0, 8.0, 4.0, radius_md.min(10.0), 12.0, false),
            Self::Sm => ButtonMetrics::new(28.0, 10.0, 4.0, radius_md.min(12.0), 12.8, false),
            Self::Default => ButtonMetrics::new(32.0, 10.0, 6.0, radius, 14.0, false),
            Self::Lg => ButtonMetrics::new(36.0, 10.0, 6.0, radius, 14.0, false),
            Self::IconXs => ButtonMetrics::new(24.0, 0.0, 0.0, radius_md.min(10.0), 14.0, true),
            Self::IconSm => ButtonMetrics::new(28.0, 0.0, 0.0, radius_md.min(12.0), 14.0, true),
            Self::Icon => ButtonMetrics::new(32.0, 0.0, 0.0, radius, 14.0, true),
            Self::IconLg => ButtonMetrics::new(36.0, 0.0, 0.0, radius, 14.0, true),
        }
    }
}

impl ButtonMetrics {
    const fn new(
        height: f32,
        horizontal_padding: f32,
        gap: f32,
        radius: f32,
        text_size: f32,
        icon_only: bool,
    ) -> Self {
        Self {
            height,
            horizontal_padding,
            gap,
            radius,
            text_size,
            icon_only,
        }
    }
}

/// A styled Button that keeps Base GPUI's pointer and keyboard behavior.
#[derive(IntoElement)]
pub struct Button {
    style: gpui::StyleRefinement,
    id: ElementId,
    variant: ButtonVariant,
    size: ButtonSize,
    disabled: bool,
    aria_label: Option<SharedString>,
    on_click: Option<ButtonClickHandler>,
    children: Vec<AnyElement>,
}

impl Button {
    /// Creates a Button with a caller-owned stable ID.
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            style: gpui::StyleRefinement::default(),
            id: id.into(),
            variant: ButtonVariant::default(),
            size: ButtonSize::default(),
            disabled: false,
            aria_label: None,
            on_click: None,
            children: Vec::new(),
        }
    }

    /// Sets the visual variant.
    pub fn variant(mut self, variant: ButtonVariant) -> Self {
        self.variant = variant;
        self
    }

    /// Sets the visual size.
    pub fn size(mut self, size: ButtonSize) -> Self {
        self.size = size;
        self
    }

    /// Prevents activation and removes the Button from tab order.
    pub fn disabled(mut self, disabled: bool) -> Self {
        self.disabled = disabled;
        self
    }

    /// Sets the accessible name, required for icon-only Buttons.
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.aria_label = Some(label.into());
        self
    }

    /// Runs for pointer, Enter, or Space activation.
    pub fn on_click(
        mut self,
        handler: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_click = Some(Rc::new(handler));
        self
    }
}

impl ParentElement for Button {
    fn extend(&mut self, elements: impl IntoIterator<Item = AnyElement>) {
        self.children.extend(elements);
    }
}

impl RenderOnce for Button {
    fn render(self, _window: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = UiTheme::read(cx).clone();
        let variant = self.variant;
        let size = self.size;
        let mut root = ButtonRoot::new()
            .id(self.id)
            .disabled(self.disabled)
            .style_with_state(move |state, base| {
                let base = { style_button(base, state.disabled, variant, size, &theme) };
                super::theme::apply_style(base, &self.style)
            })
            .children(self.children);

        if let Some(label) = self.aria_label {
            root = root.aria_label(label);
        }
        if let Some(handler) = self.on_click {
            root = root.on_click(move |event, window, cx| handler(event, window, cx));
        }

        root
    }
}

pub(super) fn style_button(
    base: Div,
    disabled: bool,
    variant: ButtonVariant,
    size: ButtonSize,
    theme: &UiTheme,
) -> Div {
    let colors = theme.colors;
    let metrics = size.metrics(theme.radius);
    let focus_border = match variant {
        ButtonVariant::Destructive => colors.destructive.opacity(0.40),
        _ => colors.ring,
    };
    let focus_ring = match variant {
        ButtonVariant::Destructive => theme.destructive_focus_ring(),
        _ => theme.focus_ring(),
    };
    let focus_background = match variant {
        ButtonVariant::Default => colors.primary,
        ButtonVariant::Outline => match theme.mode {
            ThemeMode::Light => colors.background,
            ThemeMode::Dark => colors.background.blend(colors.input.opacity(0.30)),
        },
        ButtonVariant::Secondary => colors.secondary,
        ButtonVariant::Ghost | ButtonVariant::Link => colors.background,
        ButtonVariant::Destructive => colors.background.blend(colors.destructive.opacity(
            if theme.mode == ThemeMode::Light {
                0.10
            } else {
                0.20
            },
        )),
    };

    let base = base
        .flex()
        .flex_shrink_0()
        .items_center()
        .justify_center()
        .whitespace_nowrap()
        .h(theme.space(metrics.height / 4.))
        .gap(theme.space(metrics.gap / 4.))
        .rounded(px(metrics.radius))
        .border_1()
        .border_color(colors.background.opacity(0.0))
        .font_family(theme.fonts.body.clone())
        .font_weight(FontWeight::MEDIUM)
        .text_size(theme.text(metrics.text_size))
        .focus_visible(move |style| {
            style
                .bg(focus_background)
                .border_color(focus_border)
                .shadow(focus_ring.clone())
        })
        .when(metrics.icon_only, |base| {
            base.w(theme.space(metrics.height / 4.)).p_0()
        })
        .when(!metrics.icon_only, |base| {
            base.px(theme.space(metrics.horizontal_padding / 4.))
        });

    let base = match variant {
        ButtonVariant::Default => base
            .bg(colors.primary)
            .text_color(colors.primary_foreground)
            .when(!disabled, |base| {
                base.hover(move |style| style.bg(colors.primary.opacity(0.80)))
            }),
        ButtonVariant::Outline => {
            let background = match theme.mode {
                ThemeMode::Light => colors.background,
                ThemeMode::Dark => colors.input.opacity(0.30),
            };
            let border = match theme.mode {
                ThemeMode::Light => colors.border,
                ThemeMode::Dark => colors.input,
            };
            let hover = match theme.mode {
                ThemeMode::Light => colors.muted,
                ThemeMode::Dark => colors.input.opacity(0.50),
            };
            base.bg(background)
                .text_color(colors.foreground)
                .border_color(border)
                .when(!disabled, |base| {
                    base.hover(move |style| style.bg(hover).text_color(colors.foreground))
                })
        }
        ButtonVariant::Secondary => {
            let hover = colors
                .secondary
                .blend(colors.secondary_foreground.opacity(0.08));
            base.bg(colors.secondary)
                .text_color(colors.secondary_foreground)
                .when(!disabled, |base| base.hover(move |style| style.bg(hover)))
        }
        ButtonVariant::Ghost => {
            let hover = match theme.mode {
                ThemeMode::Light => colors.muted,
                ThemeMode::Dark => colors.muted.opacity(0.50),
            };
            base.bg(colors.background.opacity(0.0))
                .text_color(colors.foreground)
                .when(!disabled, |base| {
                    base.hover(move |style| style.bg(hover).text_color(colors.foreground))
                })
        }
        ButtonVariant::Destructive => {
            let background_alpha = match theme.mode {
                ThemeMode::Light => 0.10,
                ThemeMode::Dark => 0.20,
            };
            let hover_alpha = match theme.mode {
                ThemeMode::Light => 0.20,
                ThemeMode::Dark => 0.30,
            };
            base.bg(colors.destructive.opacity(background_alpha))
                .text_color(colors.destructive)
                .when(!disabled, |base| {
                    base.hover(move |style| style.bg(colors.destructive.opacity(hover_alpha)))
                })
        }
        ButtonVariant::Link => base
            .bg(colors.background.opacity(0.0))
            .text_color(colors.primary)
            .when(!disabled, |base| base.hover(|style| style.underline())),
    };

    base.when(!disabled, |base| base.cursor_pointer())
        .when(disabled, |base| base.opacity(0.50).cursor_not_allowed())
}

impl gpui::Styled for Button {
    fn style(&mut self) -> &mut gpui::StyleRefinement {
        &mut self.style
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_variants_expose_clickable_and_disabled_cursors() {
        for theme in [UiTheme::neutral_light(), UiTheme::neutral_dark()] {
            for variant in [
                ButtonVariant::Default,
                ButtonVariant::Outline,
                ButtonVariant::Secondary,
                ButtonVariant::Ghost,
                ButtonVariant::Destructive,
                ButtonVariant::Link,
            ] {
                for disabled in [false, true] {
                    let mut button =
                        style_button(gpui::div(), disabled, variant, ButtonSize::Default, &theme);
                    assert_eq!(
                        button.style().mouse_cursor,
                        Some(if disabled {
                            gpui::CursorStyle::OperationNotAllowed
                        } else {
                            gpui::CursorStyle::PointingHand
                        })
                    );
                }
            }
        }
    }

    #[test]
    fn nova_sizes_are_exact() {
        let sizes = [
            (ButtonSize::Xs, 24.0, 8.0, 4.0, 8.0),
            (ButtonSize::Sm, 28.0, 10.0, 4.0, 8.0),
            (ButtonSize::Default, 32.0, 10.0, 6.0, 10.0),
            (ButtonSize::Lg, 36.0, 10.0, 6.0, 10.0),
            (ButtonSize::IconXs, 24.0, 0.0, 0.0, 8.0),
            (ButtonSize::IconSm, 28.0, 0.0, 0.0, 8.0),
            (ButtonSize::Icon, 32.0, 0.0, 0.0, 10.0),
            (ButtonSize::IconLg, 36.0, 0.0, 0.0, 10.0),
        ];

        for (size, height, padding, gap, radius) in sizes {
            let metrics = size.metrics(UiRadius::new(px(10.0)));
            assert_eq!(metrics.height, height);
            assert_eq!(metrics.horizontal_padding, padding);
            assert_eq!(metrics.gap, gap);
            assert_eq!(metrics.radius, radius);
        }
    }
}

//! The narrow shadcn Nova Dialog visual port.
//!
//! Visual source: shadcn/ui 4.19.0 `dialog.tsx` and `style-nova.css` at
//! `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`. Interaction, dismissal, and the
//! Popup/Close focus cycle come from the pinned Base GPUI Dialog primitives.

#[path = "modal_focus.rs"]
pub(crate) mod modal_focus;

pub use base_gpui::dialog::{
    DialogBackdrop, DialogClose, DialogDescription, DialogPopup, DialogPortal, DialogRoot,
    DialogTitle, DialogTrigger, DialogViewport,
};
use gpui::{App, Div, ElementId, FontWeight, ParentElement as _, SharedString, Styled, div, px};
use gpui_icons::{LucideIcon, lucide};

use super::{
    button::{ButtonSize, ButtonVariant, style_button},
    theme::UiTheme,
};

/// Creates the Dialog state root with a caller-owned stable ID.
pub fn dialog_root(id: impl Into<ElementId>) -> DialogRoot<()> {
    DialogRoot::new().id(id)
}

/// Creates a styled Dialog trigger with a caller-owned stable ID.
pub fn dialog_trigger(id: impl Into<ElementId>, cx: &App) -> DialogTrigger<()> {
    let theme = UiTheme::read(cx).clone();
    DialogTrigger::new()
        .id(id)
        .style_with_state(move |state, base| {
            style_button(
                base,
                state.disabled,
                ButtonVariant::Outline,
                ButtonSize::Default,
                &theme,
            )
        })
}

/// Creates the in-canvas Dialog portal.
pub fn dialog_portal() -> DialogPortal<()> {
    DialogPortal::new()
}

/// Creates the dismissible, full-window Dialog backdrop.
pub fn dialog_backdrop(cx: &App) -> DialogBackdrop<()> {
    DialogBackdrop::new()
        .absolute()
        .inset_0()
        .bg(UiTheme::read(cx).colors.overlay)
}

/// Creates the centered Dialog viewport with the pinned 16px page gutter.
pub fn dialog_viewport(cx: &App) -> DialogViewport<()> {
    let theme = UiTheme::read(cx).clone();
    let spacing = theme.spacing.unit;
    DialogViewport::new()
        .absolute()
        .inset_0()
        .flex()
        .flex_col()
        .items_stretch()
        .justify_center()
        .p(spacing * 4_f32)
}

/// Creates Nova's stacked Dialog header.
pub fn dialog_header(cx: &App) -> Div {
    let theme = UiTheme::read(cx).clone();
    let spacing = theme.spacing.unit;
    div().flex().flex_col().gap(spacing * 2_f32)
}

/// Creates Nova's inset Dialog footer surface.
pub fn dialog_footer(cx: &App) -> Div {
    let theme = UiTheme::read(cx);
    let spacing = theme.spacing.unit;
    div()
        .mx(spacing * -4_f32)
        .mb(spacing * -4_f32)
        .flex()
        .justify_end()
        .gap(spacing * 2_f32)
        .rounded_b(theme.radius.xl)
        .border_t_1()
        .border_color(theme.colors.border)
        .bg(theme.colors.muted.opacity(0.50))
        .p(spacing * 4_f32)
}

/// Creates a styled Dialog popup with a caller-owned stable ID and name.
pub fn dialog_popup(
    id: impl Into<ElementId>,
    aria_label: impl Into<SharedString>,
    cx: &App,
) -> DialogPopup<()> {
    let theme = UiTheme::read(cx).clone();
    let spacing = theme.spacing.unit;
    let text_scale = theme.text_scale;
    let id = id.into();
    let focus = modal_focus::ModalFocus::new(id.clone());
    DialogPopup::new()
        .id(id)
        .aria_label(aria_label)
        .child_any(focus.boundary(false))
        .child_any(focus.boundary(true))
        .style_with_state(move |state, base| {
            let base = focus.trap(
                base,
                state.modal_mode.traps_focus() && !state.nested_dialog_open,
            );
            base.w_full()
                .min_w(px(0.))
                .mx_auto()
                .max_w(spacing * 96_f32)
                .max_h(spacing * 100_f32)
                .overflow_hidden()
                .flex()
                .flex_col()
                .gap(spacing * 4_f32)
                .rounded(theme.radius.xl)
                .border_1()
                .border_color(theme.colors.foreground.opacity(0.10))
                .p(spacing * 4_f32)
                .bg(theme.colors.popover)
                .text_color(theme.colors.popover_foreground)
                .font_family(theme.fonts.body.clone())
                .text_size(px(14.0) * text_scale)
        })
}

/// Creates a styled Dialog title with a caller-owned stable ID.
pub fn dialog_title(id: impl Into<ElementId>, cx: &App) -> DialogTitle<()> {
    let theme = UiTheme::read(cx).clone();
    let text_scale = theme.text_scale;
    DialogTitle::new()
        .id(id)
        .font_family(theme.fonts.heading)
        .font_weight(FontWeight::MEDIUM)
        .text_size(px(16.0) * text_scale)
        .line_height(px(16.0) * text_scale)
        .text_color(theme.colors.popover_foreground)
}

/// Creates a styled Dialog description with a caller-owned stable ID.
pub fn dialog_description(id: impl Into<ElementId>, cx: &App) -> DialogDescription<()> {
    let theme = UiTheme::read(cx).clone();
    let text_scale = theme.text_scale;
    DialogDescription::new()
        .id(id)
        .font_family(theme.fonts.body)
        .text_size(px(14.0) * text_scale)
        .text_color(theme.colors.muted_foreground)
}

/// Creates the styled, icon-only Dialog close control.
pub fn dialog_close(id: impl Into<ElementId>, cx: &App) -> DialogClose<()> {
    let theme = UiTheme::read(cx).clone();
    let spacing = theme.spacing.unit;
    let icon_color = theme.colors.popover_foreground;
    DialogClose::new()
        .id(id)
        .aria_label("Close")
        .absolute()
        .top(spacing * 2_f32)
        .right(spacing * 2_f32)
        .style_with_state(move |state, base| {
            style_button(
                base,
                state.disabled,
                ButtonVariant::Ghost,
                ButtonSize::IconSm,
                &theme,
            )
        })
        .child(
            lucide(LucideIcon::X)
                .size(spacing * 4_f32)
                .text_color(icon_color),
        )
}

/// Creates a primary Dialog action that dismisses the Dialog after activation.
pub fn dialog_action(id: impl Into<ElementId>, cx: &App) -> DialogClose<()> {
    let theme = UiTheme::read(cx).clone();
    DialogClose::new()
        .id(id)
        .style_with_state(move |state, base| {
            style_button(
                base,
                state.disabled,
                ButtonVariant::Default,
                ButtonSize::Default,
                &theme,
            )
        })
}

//! Modal keyboard traversal over GPUI's actual tab stops, including app-owned
//! inputs passed through Base GPUI's `child_any` slots.

use std::{
    cell::{Cell, RefCell},
    rc::Rc,
    sync::Arc,
};

use base_gpui::dialog::{DialogFocusNextAction, DialogFocusPreviousAction};
use gpui::{
    App, Div, ElementId, FocusHandle, InteractiveElement as _, IntoElement, RenderOnce,
    SharedString, Styled, Window, div, px,
};

#[derive(Clone)]
pub(crate) struct ModalFocus {
    id: ElementId,
    enabled: Rc<Cell<bool>>,
    handles: Rc<RefCell<[Option<FocusHandle>; 2]>>,
}

impl ModalFocus {
    pub(crate) fn new(id: ElementId) -> Self {
        Self {
            id,
            enabled: Rc::default(),
            handles: Rc::default(),
        }
    }

    pub(crate) fn boundary(&self, end: bool) -> impl IntoElement {
        Boundary {
            scope: self.clone(),
            end,
        }
    }

    pub(crate) fn trap(&self, base: Div, enabled: bool) -> Div {
        self.enabled.set(enabled);
        if !enabled {
            return base;
        }
        let next = self.clone();
        let previous = self.clone();
        base.tab_group()
            .capture_action(move |_: &DialogFocusNextAction, window, cx| {
                next.advance(false, window, cx)
            })
            .capture_action(move |_: &DialogFocusPreviousAction, window, cx| {
                previous.advance(true, window, cx)
            })
    }

    fn advance(&self, reverse: bool, window: &mut Window, cx: &mut App) {
        let [Some(start), Some(end)] = self.handles.borrow().clone() else {
            return;
        };
        let original = window.focused(cx);
        if reverse {
            // The initially focused popup is the ancestor of both boundaries.
            // Enter from the end without focusing anything behind the modal.
            if start.within_focused(window, cx) {
                end.focus(window, cx);
            }
            window.focus_prev(cx);
            if start.is_focused(window) {
                end.focus(window, cx);
                window.focus_prev(cx);
            }
        } else {
            window.focus_next(cx);
            if start.is_focused(window) {
                window.focus_next(cx);
            }
            if end.is_focused(window) {
                start.focus(window, cx);
                window.focus_next(cx);
            }
        }
        if (start.is_focused(window) || end.is_focused(window))
            && let Some(original) = original
        {
            original.focus(window, cx);
        }
        window.prevent_default();
        cx.stop_propagation();
    }
}

#[derive(IntoElement)]
struct Boundary {
    scope: ModalFocus,
    end: bool,
}

impl RenderOnce for Boundary {
    fn render(self, window: &mut Window, cx: &mut App) -> impl IntoElement {
        let index = usize::from(self.end);
        let id = ElementId::NamedChild(
            Arc::new(self.scope.id),
            SharedString::from(if self.end { "tab-end" } else { "tab-start" }),
        );
        let handle = window
            .use_keyed_state(id.clone(), cx, |_, cx| cx.focus_handle())
            .read(cx)
            .clone();
        self.scope.handles.borrow_mut()[index] = Some(handle.clone());
        // Out of layout and role-less. The end's group index follows all normal
        // controls, including custom positive tab indices, although both boundaries are inserted first.
        div().id(id).absolute().size(px(0.)).track_focus(
            &handle
                .tab_stop(self.scope.enabled.get())
                .tab_index(if self.end { isize::MAX } else { 0 }),
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use gpui::{AppContext as _, Context, ParentElement as _, Render, TestAppContext};

    struct View {
        popup: FocusHandle,
        first: FocusHandle,
        last: FocusHandle,
        outside: FocusHandle,
        scope: ModalFocus,
        trap: bool,
    }
    impl Render for View {
        fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
            div().child(div().track_focus(&self.outside)).child(
                self.scope
                    .trap(div().track_focus(&self.popup), self.trap)
                    .child(self.scope.boundary(false))
                    .child(self.scope.boundary(true))
                    .child(div().track_focus(&self.first))
                    .child(div().track_focus(&self.last)),
            )
        }
    }

    #[test]
    fn modal_tab_order_includes_generic_children_and_wraps_both_ways() {
        let mut cx = TestAppContext::single();
        let (popup, first, last, outside) = cx.update(|cx| {
            (
                cx.focus_handle().tab_stop(true),
                cx.focus_handle().tab_stop(true),
                cx.focus_handle().tab_stop(true),
                cx.focus_handle().tab_stop(true),
            )
        });
        let scope = ModalFocus::new("test-modal".into());
        let window = cx.add_window({
            let (popup, first, last, outside, scope) = (
                popup.clone(),
                first.clone(),
                last.clone(),
                outside.clone(),
                scope.clone(),
            );
            move |_, _| View {
                popup,
                first,
                last,
                outside,
                scope,
                trap: true,
            }
        });
        cx.update_window(window.into(), |_, window, cx| {
            window.draw(cx).clear(cx);
            popup.focus(window, cx);
            for (reverse, expected) in [
                (false, &first),
                (false, &last),
                (false, &first),
                (true, &last),
                (true, &first),
            ] {
                scope.advance(reverse, window, cx);
                assert!(
                    expected.is_focused(window),
                    "reverse={reverse}, expected={expected:?}, actual={:?}",
                    window.focused(cx)
                );
                assert!(!outside.is_focused(window));
            }
            popup.focus(window, cx);
            scope.advance(true, window, cx);
            assert!(last.is_focused(window));
        })
        .unwrap();
        cx.update_window(window.into(), |view, window, cx| {
            view.downcast::<View>()
                .unwrap()
                .update(cx, |view, _| view.trap = false);
            window.draw(cx).clear(cx);
            popup.focus(window, cx);
            window.focus_next(cx);
            assert!(
                first.is_focused(window),
                "non-modal traversal must skip hidden boundaries"
            );
        })
        .unwrap();
    }
}

#![allow(missing_docs)]
//! Nova-styled text Input backed by Base GPUI editing and focus behavior.

use std::rc::Rc;

use base_gpui::input::Input as BaseInput;
use gpui::{
    App, ElementId, InteractiveElement as _, IntoElement, RenderOnce, SharedString, Styled, Window,
    prelude::FluentBuilder as _, px,
};

use super::theme::{ThemeMode, UiTheme, input_text_layout};

type ValueChange = Rc<dyn Fn(SharedString) + 'static>;

#[derive(IntoElement)]
pub struct Input {
    style: gpui::StyleRefinement,
    id: ElementId,
    value: Option<SharedString>,
    default_value: Option<SharedString>,
    placeholder: Option<SharedString>,
    aria_label: Option<SharedString>,
    disabled: bool,
    read_only: bool,
    required: bool,
    on_value_change: Option<ValueChange>,
}

impl Input {
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            style: gpui::StyleRefinement::default(),
            id: id.into(),
            value: None,
            default_value: None,
            placeholder: None,
            aria_label: None,
            disabled: false,
            read_only: false,
            required: false,
            on_value_change: None,
        }
    }
    pub fn value(mut self, value: impl Into<SharedString>) -> Self {
        self.value = Some(value.into());
        self
    }
    pub fn default_value(mut self, value: impl Into<SharedString>) -> Self {
        self.default_value = Some(value.into());
        self
    }
    pub fn placeholder(mut self, value: impl Into<SharedString>) -> Self {
        self.placeholder = Some(value.into());
        self
    }
    pub fn aria_label(mut self, value: impl Into<SharedString>) -> Self {
        self.aria_label = Some(value.into());
        self
    }
    pub fn disabled(mut self, value: bool) -> Self {
        self.disabled = value;
        self
    }
    pub fn read_only(mut self, value: bool) -> Self {
        self.read_only = value;
        self
    }
    pub fn required(mut self, value: bool) -> Self {
        self.required = value;
        self
    }
    pub fn on_value_change(mut self, handler: impl Fn(SharedString) + 'static) -> Self {
        self.on_value_change = Some(Rc::new(handler));
        self
    }
}

impl RenderOnce for Input {
    fn render(self, _window: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = UiTheme::read(cx).clone();
        let spacing = theme.spacing.unit;
        let text_scale = theme.text_scale;
        let colors = theme.colors;
        let background = match theme.mode {
            ThemeMode::Light => colors.background,
            ThemeMode::Dark => colors.background.blend(colors.input.opacity(0.30)),
        };
        let mut input = BaseInput::new()
            .id(self.id)
            .disabled(self.disabled)
            .read_only(self.read_only)
            .required(self.required)
            .font_family(theme.fonts.body.clone())
            .style_with_state(move |state, base| {
                let base = {
                    let focus_ring = if state.invalid {
                        theme.destructive_focus_ring()
                    } else {
                        theme.focus_ring()
                    };
                    let border = if state.invalid {
                        colors.destructive.opacity(match theme.mode {
                            ThemeMode::Light => 1.0,
                            ThemeMode::Dark => 0.50,
                        })
                    } else {
                        colors.input
                    };
                    input_text_layout(base, text_scale)
                        .w_full()
                        .min_w_0()
                        .h(spacing * 8_f32)
                        .px(spacing * 2.5_f32)
                        .rounded(theme.radius.lg)
                        .border_1()
                        .border_color(border)
                        .bg(if state.disabled {
                            colors.input.opacity(match theme.mode {
                                ThemeMode::Light => 0.50,
                                ThemeMode::Dark => 0.80,
                            })
                        } else {
                            background
                        })
                        .text_color(colors.foreground)
                        .text_size(px(14.) * text_scale)
                        .focus_visible(move |style| {
                            style
                                .border_color(if state.invalid { border } else { colors.ring })
                                .shadow(focus_ring.clone())
                        })
                        .when(state.disabled, |base| base.cursor_not_allowed())
                };
                super::theme::apply_style(base, &self.style)
            });
        if let Some(value) = self.value {
            input = input.value(value);
        }
        if let Some(value) = self.default_value {
            input = input.default_value(value);
        }
        if let Some(value) = self.placeholder {
            input = input.placeholder(value);
        }
        if let Some(value) = self.aria_label {
            input = input.aria_label(value);
        }
        if let Some(handler) = self.on_value_change {
            input = input.on_value_change(move |value| handler(value));
        }
        input
    }
}

impl gpui::Styled for Input {
    fn style(&mut self) -> &mut gpui::StyleRefinement {
        &mut self.style
    }
}

